        this.addAnnotation((ENamedElement)this.dataWriteAccessEClass, source, new String[]{"documentation", "The presences of a DataWriteAccess means that the runnable will potentially modify the dataElement in the pPort. The runnable has free access to the data-element while it is running. The runnable has the responsibility to make sure that the data-element is in a consistent state when it returns. When using DataWriteAccess the new values of the data-element is not made available via the communication infrastrucure before the runnable returns (exits the \"Running\" state)."});
        this.addAnnotation((ENamedElement)this.getDataWriteAccess_DataElement(), source, new String[]{"documentation", "The data element that is going to be written to by this runnable."});
